import {warehouseRepository} from './auth-client.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let rows=[],editing=null,sharing=null,callbacks={};
export async function refreshWarehouses(){try{rows=await warehouseRepository.list();$('#warehouseListError').textContent='';render()}catch(e){$('#warehouseListError').textContent=e.message;throw e}}
function render(){const current=window.wsmsSession?.warehouse?.id||'';$('#projectName').innerHTML='<option value="">Choose a warehouse</option>'+rows.map(w=>`<option value="${esc(w.id)}">${esc(w.name)}</option>`).join('');$('#projectName').value=current;$('#warehouseList').innerHTML=rows.length?`<div class="warehouseTableWrap"><table class="warehouseTable"><thead><tr><th>Warehouse</th><th>Country</th><th>Location</th><th>Your role</th><th>Open workspace</th><th></th></tr></thead><tbody>${rows.map(w=>`<tr><td><strong>${esc(w.name)}</strong><small>Owner · ${esc(w.ownerEmail)}</small></td><td>${esc(w.country)||'—'}</td><td>${esc(w.location)||'—'}</td><td><span class="roleBadge ${esc(w.role)}">${esc(w.role)}</span></td><td><div class="warehouseActions">${w.role!=='viewer'?`<button data-launch="${esc(w.id)}">Open editor ↗</button>`:''}<button data-overview-launch="${esc(w.id)}">Overview ↗</button></div></td><td><div class="warehouseActions">${w.role!=='viewer'?`<button data-edit-warehouse="${esc(w.id)}">Details</button>`:''}${w.role==='owner'?`<button data-share="${esc(w.id)}">Share</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:'<div class="warehouseEmpty"><span>▧</span><h2>A space for every warehouse</h2><p>Create your first warehouse, or ask an owner to add your account email.</p><button data-new-warehouse>＋ Create warehouse</button></div>';}
function edit(w=null){editing=w?.id||null;$('#warehouseDialogTitle').textContent=w?'Warehouse details':'New warehouse';const form=$('#warehouseForm');for(const key of ['name','country','location'])form.elements[key].value=w?.[key]||'';$('#warehouseFormError').textContent='';$('#warehouseDialog').showModal();form.elements.name.focus();}
async function open(id,destination){const selector=$('#projectName'),previous=window.wsmsSession?.warehouse?.id||'';selector.disabled=true;$('#warehouseSwitchError').textContent='';try{await callbacks.beforeOpen?.();const data=await warehouseRepository.load(id);await callbacks.onOpen?.(data,destination);$('#warehouseListError').textContent='';return true}catch(e){$('#warehouseListError').textContent=e.message;$('#warehouseSwitchError').textContent=e.message;selector.value=previous;return false}finally{selector.disabled=false}}
async function renderSharing(){try{const members=await warehouseRepository.members(sharing);$('#memberList').innerHTML=members.map(m=>`<div class="memberRow"><div><b>${esc(m.email)}</b><small>${esc(m.role)}</small></div>${m.role==='owner'?'<span class="roleBadge">Owner</span>':`<select aria-label="Role for ${esc(m.email)}" data-member-role="${esc(m.email)}"><option value="viewer" ${m.role==='viewer'?'selected':''}>Viewer</option><option value="editor" ${m.role==='editor'?'selected':''}>Editor</option></select><button data-remove-member="${esc(m.email)}">Remove</button>`}</div>`).join('')}catch(e){$('#sharingError').textContent=e.message}}
export async function initWarehouses(handlers){callbacks=handlers;$('#projectName').onchange=async e=>{if(!e.target.value){e.target.value=window.wsmsSession?.warehouse?.id||'';return}if(e.target.value&&e.target.value!==window.wsmsSession?.warehouse?.id)await open(e.target.value,'overview')};$('#newWarehouse').onclick=()=>edit();$('#warehouseList').onclick=async e=>{const button=e.target.closest('button');if(!button)return;if(button.hasAttribute('data-new-warehouse'))edit();if(button.dataset.launch)await open(button.dataset.launch,'editor');if(button.dataset.overviewLaunch)await open(button.dataset.overviewLaunch,'overview');if(button.dataset.editWarehouse)edit(rows.find(w=>w.id===button.dataset.editWarehouse));if(button.dataset.share){sharing=button.dataset.share;$('#sharingTitle').textContent='Access · '+rows.find(w=>w.id===sharing).name;$('#sharingError').textContent='';$('#sharingDialog').showModal();await renderSharing()}};
$('#warehouseForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type="submit"]');button.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));const w=editing?await warehouseRepository.update(editing,data):await warehouseRepository.create(data);$('#warehouseDialog').close();await refreshWarehouses();callbacks.onDetails?.(w)}catch(e){$('#warehouseFormError').textContent=e.message}finally{button.disabled=false}};document.querySelectorAll('[data-close-warehouse]').forEach(b=>b.onclick=()=>$('#warehouseDialog').close());$('#closeSharing').onclick=()=>$('#sharingDialog').close();$('#memberForm').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.target);try{await warehouseRepository.setMember(sharing,data.get('email'),data.get('role'));$('#sharingError').textContent='';e.target.reset();await renderSharing()}catch(e){$('#sharingError').textContent=e.message}};$('#memberList').onchange=async e=>{const email=e.target.dataset.memberRole;if(!email)return;try{await warehouseRepository.setMember(sharing,email,e.target.value);$('#sharingError').textContent='';await renderSharing()}catch(e){$('#sharingError').textContent=e.message}};$('#memberList').onclick=async e=>{const email=e.target.closest('[data-remove-member]')?.dataset.removeMember;if(!email)return;try{await warehouseRepository.removeMember(sharing,email);await renderSharing()}catch(e){$('#sharingError').textContent=e.message}};await refreshWarehouses();}
